(() => {
  const cards = Array.from(document.querySelectorAll('.draggable-item, [draggable="true"]')).map(c => ({tag:c.tagName, cls:c.className, tid:c.getAttribute('data-task-id'), text:(c.innerText||'').replace(/\s+/g,' ').slice(0,50)}));
  const cols = Array.from(document.querySelectorAll('td.board-swimlane-column')).map(td => ({cls:td.className, colId:td.getAttribute('data-column-id'), title:(td.querySelector('th')?.innerText||'').replace(/\s+/g,' ').slice(0,30)}));
  return {cards, cols};
})()

(() => {
  const card = document.querySelector('.draggable-item[data-task-id="4"]');
  const chain = [];
  let el = card;
  for (let i=0;i<5 && el;i++){ chain.push({tag:el.tagName, cls:el.className, colId:el.getAttribute('data-column-id'), swim:el.getAttribute('data-swimlane-id')}); el = el.parentElement; }
  const headers = Array.from(document.querySelectorAll('th')).map(th=>({cls:th.className, txt:(th.innerText||'').replace(/\s+/g,' ').slice(0,40), colId:th.getAttribute('data-column-id')}));
  return {chain, headers};
})()

(() => {
  const card = document.querySelector('.draggable-item[data-task-id="4"]');
  const td = card ? card.closest('td[class*="board-column-"]') : null;
  return {
    cardFound: !!card,
    cardText: card ? card.innerText.replace(/\s+/g,' ').slice(0,60) : null,
    columnClass: td ? td.className.trim() : null,
    colId: card ? card.getAttribute('data-column-id') : null,
    perColumn: Array.from(document.querySelectorAll('tbody tr.board-swimlane')).map(tr => Array.from(tr.querySelectorAll('td[class*="board-column-"]')).filter(td=>/\d/.test(td.className)).map(td=>({cls:td.className.trim(), tasks:Array.from(td.querySelectorAll('.draggable-item')).map(c=>c.getAttribute('data-task-id'))})))
  };
})()

(() => {
