(() => {
  const inputs = Array.from(document.querySelectorAll('input, select, textarea')).map(e=>({id:e.id, name:e.name, type:e.type, val:e.value, label:(document.querySelector('label[for="'+e.id+'"]')?.innerText||'').trim().slice(0,30), ph:e.placeholder}));
  return inputs.filter(i => JSON.stringify(i).match(/due|date/i));
})()

(() => {
  const txt = document.body.innerText;
  const m = txt.match(/Due date[^\n]*\n?[^\n]*/i);
  const due = Array.from(document.querySelectorAll('li, dt, dd, span, div')).filter(e=>/Due date/i.test(e.textContent) && e.children.length<3).map(e=>e.innerText.replace(/\s+/g,' ').trim()).slice(0,5);
  return {due, hasComment: txt.includes('Comment for run jgkb1g45r2-n1')};
})()

(() => {
  const lists = document.querySelectorAll('#task-summary ul, .task-summary-container ul, form ~ ul');
  const kv = [];
  document.querySelectorAll('li').forEach(li => {
    const s = li.querySelector('strong');
    if (s) {
      const full = li.innerText.replace(/\s+/g,' ').trim();
      if (full.length < 90) kv.push(full);
    }
  });
  const title = document.querySelector('h2')?.innerText;
  const descArticles = Array.from(document.querySelectorAll('.markdown, article')).map(a=>a.innerText.trim());
  const comments = Array.from(document.querySelectorAll('.comment, .comment-body, .comment-text, .comment-content')).map(c=>c.innerText.replace(/\s+/g,' ').trim());
  return {kv, title, descArticles, comments};
})()

(() => {
  const card = document.querySelector('.draggable-item[data-task-id="4"]');
