  return {
    cardText: card.innerText.replace(/\s+/g,' ').trim(),
    cardIdAttr: card.getAttribute('data-task-id'),
    columnClass: td.className.trim(),
    columnHeader: td.closest('tr') ? document.querySelectorAll('th')[Array.from(document.querySelectorAll('td[class*="board-column-"]')).indexOf(td)]?.innerText.replace(/\s+/g,' ').trim() : null,
    allCards: Array.from(document.querySelectorAll('.draggable-item')).map(c=>({id:c.getAttribute('data-task-id'), title:c.querySelector('a[href*="task_id"]')?.innerText.trim(), col:c.closest('td[class*="board-column-"]').className.trim()}))
  };
})()
